const items = $input.all();
const allowedPurpose = new Set(['Хочу купити','Хочу орендувати','Хочу продати','Хочу здати в оренду']);
const allowedType = new Set(['Квартира','Будинок','Комерційне приміщення','Земля']);

const results = [];
for (const item of items) {
  const data = item.json.body ?? item.json;
  const required = (name, alt) => {
    const v = String(data[name] ?? (alt ? data[alt] : '') ?? '').trim();
    if (!v) throw new Error(`Порожнє обов'язкове поле: ${name}`);
    return v;
  };
  try {
    const full_name = required('ПІБ', 'full_name');
    const phone = required('Контактний телефон', 'phone');
    if (!/^\+?[0-9 ()-]{10,20}$/.test(phone)) continue;
    const request_purpose = required('Ціль запиту', 'request_purpose');
    const property_type = required('Тип нерухомості', 'property_type');
    if (!allowedPurpose.has(request_purpose)) continue;
    if (!allowedType.has(property_type)) continue;
    const property_location = required("Місцезнаходження об'єкта", 'property_location');
    const rawDate = required('Бажана дата консультації', 'consultation_date');
    let consultation_date;
    let m = rawDate.match(/^(\d{4})-(\d{2})-(\d{2})$/);
    if (m) consultation_date = rawDate;
    else {
      m = rawDate.match(/^(\d{2})[./](\d{2})[./](\d{4})$/);
      if (!m) continue;
      consultation_date = `${m[3]}-${m[2]}-${m[1]}`;
    }
    const parsed = new Date(`${consultation_date}T00:00:00Z`);
    if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0,10) !== consultation_date) continue;
    const sourceTimestamp = String(data['Отметка времени'] ?? data['Позначка часу'] ?? data['Відмітка часу'] ?? data.Timestamp ?? data.timestamp ?? new Date().toISOString()).trim();
    const source_row_id = String(data.source_row_id ?? `19yHm6hi7G2b8s3y8pFVSoCn8m3HiWJDlFr_CdXMnoUg:567687119:${encodeURIComponent(sourceTimestamp)}:${encodeURIComponent(phone)}:${encodeURIComponent(full_name)}`);
    const additional_comments = String(data['Додаткові коментарі'] ?? data.additional_comments ?? '').trim() || null;
    results.push({ json: { full_name, phone, request_purpose, property_type, property_location, consultation_date, additional_comments, source_row_id } });
  } catch (e) {
    // skip invalid item
  }
}
return results;

